code.cpp:
class Solution {
public:
    vector<int> findDuplicates(vector<int>& nums) {
        vector<int> result;
        for (int i = 0; i < (int)nums.size(); i++) {
            int idx = abs(nums[i]) - 1;
            if (nums[idx] < 0) {
                result.push_back(idx + 1);
            } else {
                nums[idx] = -nums[idx];
            }
        }
        return result;
    }
};
